def transform(grid):
    """Draw a color-3 separator across the empty row between two figures."""
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0]) if h else 0
    for r in range(1, h - 1):
        if all(v == 0 for v in out[r]) and any(v != 0 for row in out[:r] for v in row) and any(v != 0 for row in out[r + 1:] for v in row):
            out[r] = [3] * w
    return out
